<?php
require_once 'config.php'; require_once 'includes/auth_check.php'; require_once 'includes/pdf_helper.php';
$id=(int)($_GET['id']??0); $stmt=$conn->prepare('SELECT c.*, d.name department_name FROM complaints c LEFT JOIN departments d ON d.id=c.department_id WHERE c.id=? AND (c.user_id=? OR ?=1) LIMIT 1'); $isAdmin=(($_SESSION['user_role']??'')==='admin')?1:0; $stmt->bind_param('iii',$id,$_SESSION['user_id'],$isAdmin);$stmt->execute();$c=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$c){http_response_code(404);exit('Complaint not found.');}
$lines=['Reference: '.$c['reference_no'],'Subject: '.$c['subject'],'Category: '.$c['category'],'Priority: '.$c['priority'],'Status: '.$c['status'],'Submitted: '.$c['created_at'],'SLA due: '.($c['sla_due_at']??'Not calculated'),'Department: '.($c['department_name']??'Unassigned'),'Anonymous submission: '.((int)$c['is_anonymous']?'Yes':'No'),'','Description:',wordwrap(strip_tags($c['description']),90,"\n",true),'','Generated: '.date('Y-m-d H:i:s')]; output_text_pdf('complaint-'.$c['reference_no'].'.pdf','Grievance Portal - Complaint Receipt',$lines);
